 rows.Add(new{uniqueID="ground",prefabPath="Prefabs/Environment/Ground",localPosition=V(0,0,0),localScale=V(1,1,1),componentData2=new[]{Comp("Ground","GroundData",new{colliderOffset=new{x=0,y=.4375},colliderSize=new{x=r.Width,y=.875}})}});
 for(int i=0;i<r.TileCount;i++)rows.Add(new{uniqueID="tile"+i,prefabPath="Prefabs/Environment/Tile Big",localPosition=V(r.TileLeft(i),0,0),localScale=V(1,1,1),componentData2=new[]{Comp("Tile","TileData",new{noGround=false,noSnow=false})}});
 foreach(bool left in new[]{true,false})rows.Add(new{uniqueID=left?"left":"right",prefabPath=PalaceDedicatedEndpoints.BeachPrefabPath,localPosition=V(left?r.BeachLeftX:r.BeachRightX,0,0),localScale=V(left?1:-1,1,1),componentData2=Array.Empty<object>()});
 return JsonSerializer.Serialize(new{land=0,_levelEdges=new{min=r.Left,max=r.Right},objects=rows});}
