 static int Main(string[] args){root=args[0];Directory.CreateDirectory(root);var r=PalaceLayoutRecipe.Capital400;var c=Fresh();Check(Get(c,r,out var d,out var why)&&d.Support==PalaceDestinationSupport.Fresh,"fresh four witnesses "+why);Check(PalaceDestinationAdmission.TryFreezeForCharge(Managers.Inst.game,c,d,out var frozen,out why)&&ReferenceEquals(d,frozen),"fresh freeze "+why);File.WriteAllText(Path.Combine(Filer.folder,"actual-target12"),"arrived-after-prepare");Check(!PalaceDestinationAdmission.TryFreezeForCharge(Managers.Inst.game,c,d,out _,out _),"target appeared after prepare denies freeze");
