 c=Existing(r);Check(Get(c,r,out d,out why)&&d.Support==PalaceDestinationSupport.SupportedSaved,"saved400 producer "+why);string before=c._islands[12].Json;c._islands[12].Json=before.Replace("tile0","differentUID");Check(PalaceDestinationAdmission.TryDescribeDestination(c,r,out _,out _),"CanPay reads lightweight samecount cache");Check(!PalaceDestinationAdmission.TryFreezeForCharge(Managers.Inst.game,c,d,out _,out _),"samecount content drift rejected at freeze");
 c=Existing(r);c._islands[12].Json=c._islands[12].Json.Replace("\"land\":0","\"land\":12");Check(Get(c,r,out _,out why),"saved land0 global and native RAM12 are the legal hydration alias "+why);
 c=Existing(r);c._islands[12].Json=c._islands[12].Json.Replace("\"land\":0","\"land\":8");WriteGlobal(c,c._islands[12].Json);Check(!Get(c,r,out _,out _),"foreign saved land8 rejected");
 c=Existing(PalaceLayoutRecipe.Known44);Check(!Get(c,r,out _,out why)&&why.Contains("RequiresExplicitMigration"),"old44 refuses400 before charge "+why);c=Existing(PalaceLayoutRecipe.Known44);Check(Get(c,PalaceLayoutRecipe.Known44,out _,out why),"known44 explicit compatibility "+why);
 c=Existing(r);c._islands[12].Json=c._islands[12].Json.Replace("\"uniqueID\":\"tile1\"","\"uniqueID\":\"tile0\"");WriteGlobal(c,c._islands[12].Json);Check(!Get(c,r,out _,out _),"saved duplicate UID denies producer");
 c=Existing(r);c._islands[12].Json=c._islands[12].Json.Replace("-192.6875","-14.6875");WriteGlobal(c,c._islands[12].Json);Check(!Get(c,r,out _,out _),"saved shore left at old middle denies producer");
 c=Existing(r);c._islands[12].Json=c._islands[12].Json.Replace(":400",":44");WriteGlobal(c,c._islands[12].Json);Check(!Get(c,r,out _,out _),"saved wrong Ground refuses");c=Fresh();Check(Get(c,r,out d,out _),"refresh seed");var proof=new PalacePaidFileProof{Owner=d.Owner};File.WriteAllBytes(Path.Combine(Filer.folder,GlobalSaveData.filename),Zip(Global(c,"null").Replace("\"currentLand\":8","\"currentLand\":8,\"paidSourceRevision\":1")));proof.RawSaveSha256=Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(Path.Combine(Filer.folder,GlobalSaveData.filename)))).ToLowerInvariant();Check(PalaceDestinationAdmission.TryRefreshAfterPaidSourceSave(Managers.Inst.game,c,r,proof,out var refreshed,out why)&&ReferenceEquals(refreshed.Recipe,r),"legal paid save refresh same key "+why);Check(PalaceDestinationAdmission.TryFreezeForCharge(Managers.Inst.game,c,refreshed,out _,out why),"refreshed proof freeze "+why);
 File.Move(Path.Combine(Filer.folder,GlobalSaveData.filename),Path.Combine(Filer.folder,"held-global"));Check(PalaceDestinationAdmission.TryDescribeDestination(c,r,out _,out _),"CanPay decision remains cache-only even when IO would fail");Check(!PalaceDestinationAdmission.TryFreezeForCharge(Managers.Inst.game,c,refreshed,out _,out _),"freeze detects unreadable global");
 c=Fresh();Check(Get(c,r,out d,out _),"container-refresh seed");var newProof=new PalacePaidFileProof{Owner=d.Owner};c._islands=new NativeList<IslandSaveData>();WriteGlobal(c);newProof.RawSaveSha256=Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(Path.Combine(Filer.folder,GlobalSaveData.filename)))).ToLowerInvariant();Check(!PalaceDestinationAdmission.TryDescribeDestination(c,r,out _,out _),"container drift invalidates CanPay cache");Check(PalaceDestinationAdmission.TryRefreshAfterPaidSourceSave(Managers.Inst.game,c,r,newProof,out _,out _),"explicit paid-save permits new container with same fully-proven destination");

 c=Fresh();ExtensionIslandRuntime.Ready=false;Check(!Get(c,r,out _,out _),"attempt failure table not-ready is sticky when API called directly");ExtensionIslandRuntime.Ready=true;Check(!Get(c,r,out _,out _),"same-epoch terminal failure not re-captured");
 c=Fresh();Check(Get(c,r,out d,out _),"same-epoch recipe seed");PalaceDestinationAdmission.NoteDestinationPrepare(c,PalaceLayoutRecipe.Known44);Check(!PalaceDestinationAdmission.TryDescribeDestination(c,r,out _,out _),"same-epoch recipe switch invalidates, never re-captures");
 c=Existing(PalaceLayoutRecipe.Known44);var legacyTrip=new PalaceTripRecord{Version=3,TripId="legacy",CampaignGuid=PalaceSaveBindingSource.Current.SemanticGuid,CampaignSlot=0,Reign=3};Check(PalaceDestinationAdmission.TryResolveTripLayout(c,legacyTrip,out var legacyRecipe,out why)&&ReferenceEquals(legacyRecipe,PalaceLayoutRecipe.Known44),"strict v3 actual saved44 evidence "+why);File.Move(PalaceCourtArea.Sidecar,PalaceCourtArea.Sidecar+".held");Check(PalaceDestinationAdmission.TryResolveTripLayout(c,legacyTrip,out _,out _),"same cold epoch reuses proof without sidecar IO");Managers.Inst.game=new Game();Check(!PalaceDestinationAdmission.TryResolveTripLayout(c,legacyTrip,out _,out _),"new Game cannot reuse old cold proof");
