 Check(!PalaceDestinationAdmission.TryGetResourcePrecheck(r,out why)&&why.Contains("R12"),"400 cannot borrow old resources");Check(PalaceDestinationAdmission.TryGetResourcePrecheck(PalaceLayoutRecipe.Known44,out _),"44 legacy resource result retained");Console.WriteLine($"D exact extracted producer: passed={passed} failed={failed}");return failed==0?0:1;}
